const Ajv = require('ajv')
const fs = require('fs')

const schema = {
  type: 'object',
  properties: {
    length: { anyOf: [{ type: 'null' }, { type: 'number' }] }
  }
}

for (const coerceTypes of [true, 'array', false]) {
  const ajv = new Ajv({ coerceTypes })
  const v = ajv.compile(schema)
  const data = { length: 0 }
  const ok = v(data)
  console.log('coerceTypes=', coerceTypes, ok, JSON.stringify(data))
}

console.log(fs.readFileSync(require.resolve('ajv/dist/compile/validate/dataType.js'), 'utf8')
  .split('\n').filter(l => /null|coerce/i.test(l)).join('\n'))

